 app.innerHTML=`${backButton()}<section class="page-title"><h1>Foto</h1></section><div class="feature-empty photo-empty"><div class="feature-mark">${icon("photo")}</div><h2>Foto Dotous</h2><p>Konten foto akan hadir di sini.</p></div>`;
